    return `<svg class="chart" viewBox="0 0 520 180" role="img" aria-label="Current weekly project demand compared with availability-adjusted capacity">${[0,.25,.5,.75,1].map(f=>{const x=143+335*f;return `<line x1="${x}" x2="${x}" y1="25" y2="145" class="chart-gridline"/><text x="${x}" y="165" text-anchor="middle" class="chart-label">${Math.round(max*f)}h</text>`;}).join("")}${rows.map((row,i)=>{const y=48+i*58;return `<text x="132" y="${y+15}" text-anchor="end" class="chart-label">${row.label}</text><rect x="143" y="${y}" width="${335*row.value/max}" height="24" rx="4" fill="${row.color}" opacity=".84"/><text x="${Math.min(493,151+335*row.value/max)}" y="${y+16}" class="chart-label">${Math.round(row.value)}h</text>`;}).join("")}</svg>`;
